import{_ as a}from"./chunks/deformable_terrain_car.BM6NLhDJ.js";import{_ as r,o as s,c as i,a5 as t}from"./chunks/framework.DrDMl0tG.js";const f=JSON.parse('{"title":"Rayrai Example: Deformable Terrain","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_deformable_terrain.md","filePath":"sections/examples/rayrai/rayrai_deformable_terrain.md"}'),o={name:"sections/examples/rayrai/rayrai_deformable_terrain.md"};function n(d,e,l,h,p,c){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="rayrai-example-deformable-terrain" tabindex="-1">Rayrai Example: Deformable Terrain <a class="header-anchor" href="#rayrai-example-deformable-terrain" aria-label="Permalink to &quot;Rayrai Example: Deformable Terrain&quot;">​</a></h1><p><img src="'+a+'" alt="The off-road buggy driving across deformable soil"></p><p><em>The buggy and its dampers are licensed under CC BY 4.0 and credited in <a href="./../../AssetCredits.html#off-road-buggy-and-race-venue">Asset Credits</a>.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>An off-road buggy drives automatically across a 16 m by 6 m soil bed, leaving permanent wheel ruts. The deformable height mesh responds to the wheel loads and slip, while the buggy&#39;s double-wishbone suspension follows the changing surface. The camera follows the car.</p><p>The example renders in process with <code>raisin::RayraiWindow</code>; it needs no TCP viewer. See <a href="./../../DeformableTerrain.html">Deformable terrain</a> for the soil model and <a href="./rayrai_offroad_buggy.html">Off-Road Buggy</a> for the vehicle.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_deformable_terrain</span></span></code></pre></div><p>On Windows, run <code>build-examples/bin/rayrai_deformable_terrain.exe</code>.</p><p>CMake target: <code>rayrai_deformable_terrain</code>. Source: <code>examples/src/rayrai/physics/rayrai_deformable_terrain.cpp</code>. The example reads the buggy&#39;s URDF and meshes from <code>rsc/offroad_buggy</code>, which CMake copies next to the executables.</p><p>To run without a window for a fixed number of physics steps:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_deformable_terrain</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --steps=3000</span></span></code></pre></div><p>Options: <code>--hidden</code> renders in a hidden window; <code>--steps=N</code> limits the number of physics steps; <code>--export=DIR</code> saves the world as <code>world.xml</code> and its assets; <code>--activation-key=FILE</code> selects a RaiSim activation key.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li><code>World::addDeformableTerrain</code> creates a 201 by 76 sample soil mesh.</li><li>Physics runs at a 1 ms time step, with 16 steps per rendered frame.</li><li>The driver maintains about 0.8 m/s and brakes near the end of the bed.</li><li>On exit, the example reports the car&#39;s speed, wheel loads, suspension loop error, terrain contact rows and maximum permanent rut depth, and checks that the car and soil state remain finite.</li></ul>',15)])])}const u=r(o,[["render",n]]);export{f as __pageData,u as default};
